  "tradeOffs": [
    {
      "choice": "Keep the bucket in one shared store instead of a bucket per gateway node",
      "gains": "One limit for the whole fleet: a client cannot multiply its allowance by hitting different nodes.",
      "costs": "A network round trip on every request — 0.4 ms median, 2.1 ms p99 — and the limiter's correctness now depends on that store's health.",
      "sourceChunkIds": [
        "source-1#chunk-2"
      ]
    },
    {
      "choice": "Token bucket instead of a fixed per-minute window",
      "gains": "Bursts are bounded by the capacity no matter where the clock is, so the boundary trick that reached 2 times the limit is gone.",
      "costs": "More state and math per key: a token count, a timestamp and a refill calculation, where the fixed window needed a single counter.",
      "sourceChunkIds": [
        "source-1#chunk-2",
        "source-2#chunk-1"
      ]
    },
    {
      "choice": "Sliding window log instead of an approximate counter",
      "gains": "Exact counting of requests in the window, with no burst allowance at all.",
      "costs": "Memory grows with the limit: 8 bytes per timestamp, about 8 KB per active key, roughly 4 GB across 500,000 active keys.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ]
    },
    {
      "choice": "Fail closed on store failure instead of fail open",
      "gains": "Traffic the limiter cannot count is refused, so a downstream dependency never sees more than its contracted rate.",
      "costs": "A slow store becomes user-visible refusals: Larkspur now accepts delayed payments instead of serving them uncounted.",
      "sourceChunkIds": [
        "source-2#chunk-2",
        "source-3#chunk-2"
      ]
    },
    {
      "choice": "Keep local fallback but divide the limit by the number of instances",
      "gains": "During a store outage the instances together still stay within the contracted rate.",
      "costs": "Requests are then counted per instance rather than per caller, and each instance only gets its share of the total.",
      "sourceChunkIds": [
        "source-2#chunk-2",
        "source-3#chunk-2"
      ]
    },
    {
      "choice": "Raise the store timeout to sit above a cross-zone round trip",
      "gains": "A store replica in another zone no longer trips the failure policy on latency alone.",
      "costs": "When the store is slow, requests wait longer instead of failing fast — the incident fix accepts delays on some payments.",
      "sourceChunkIds": [
        "source-3#chunk-2"
      ]
    }
  ],
  "rejectedAlternatives": [
